const body = $input.first().json;
const e = body.event || 'onboarding.unknown';
const d = body.data || {};
const plan = d.plan || {};
const ms = d.milestone || {};
const pulse = d.pulse || {};
const task = d.task || {};

function line(event) {
  if (event === 'onboarding.plan_created') return `🟢 New onboarding plan \`${plan.id || ''}\` — team \`${plan.team_id || ''}\` user \`${plan.user_id || ''}\` — starts ${plan.start_date || ''}`;
  if (event === 'onboarding.plan_generated') return `🤖 AI plan generated for ${plan.repo_url || plan.notes || ''} — plan \`${plan.id || ''}\``;
  if (event === 'onboarding.plan_updated') return `✏️ Plan updated \`${plan.id || ''}\` — status \`${plan.status || ''}\``;
  if (event === 'onboarding.milestone_completed') return `✅ Milestone completed: *${ms.title || ''}* (Day ${ms.day_target || ''}) — plan \`${plan.id || ''}\``;
  if (event === 'onboarding.preboarding_completed') return `📋 Pre-boarding done: *${task.title || ''}* — plan \`${plan.id || ''}\``;
  if (event === 'onboarding.pulse_submitted') return `💬 Pulse week ${pulse.week_number || ''}: confidence ${pulse.confidence_score ?? '?'} /10, sentiment ${pulse.sentiment || ''} — plan \`${plan.id || ''}\``;
  if (event === 'onboarding.test') return `🧪 ${d.test_message || 'Onramp ↔ n8n ↔ Telegram test — onboarding is wired.'}`;
  return `ℹ️ ${event}`;
}

const text = line(e) + `\n\n_${e} • ${new Date().toISOString()}_`;
const chatId = $input.first().json.data?.chat_id || $input.first().json.data?.plan?.telegram_chat_id || '{{$json["telegram_chat_id"]}}';
return [{ json: { text, chatId, event: e, raw: body } }];
